        {
          "id": "cMrE7oz3K11aJZtC",
          "name": "Glimpse of Stolen Flesh",
          "kind": "passive",
          "description": "30 feet. When a creature ends its turn in the aura, it sees pieces of its own body amid the interlocutor's form. The creature must succeed at a check (will, dc:33) save or become Stunned 1.",
          "traits": [
            "aura",
            "divine",
            "fear",
            "mental",
            "visual"
          ]
        },
        {
          "id": "sjk7gsZB7YAEVqjS",
          "name": "Focus Gaze",
          "kind": "action",
          "description": "The interlocutor stares at a creature they can see within 30 feet. The creature must immediately attempt a Will save against glimpse of stolen flesh. In addition, if the creature was already Stunned, on a failed save, it feels its internal organs twist and writhe, and is Clumsy 2 for 1 minute.\nAfter attempting this save, the creature is then temporarily immune until the start of the interlocutor's next turn.",
          "traits": [
            "concentrate",
            "divine",
            "fear",
            "mental",
            "visual"
          ]
        },
        {
          "id": "T5aqHU7uB2IvWwrg",
          "name": "Surgical Rend",
          "kind": "action",
          "description": "This functions as the Rend ability, dealing claw damage. In addition, if the target is a living creature with organs and muscle, the interlocutor opens a precise wound. Until the creature is restored to its maximum Hit Points, thus closing the wound, Strikes against the creature deal 1d6 extra precision damage.\nEffect: Surgical Rend",
          "traits": []
        }
