        {
          "id": "WNOqI0v6YF697eJv",
          "name": "Bloodline Magic",
          "kind": "passive",
          "description": "When Raven casts a bloodline spell, she gains Concealment for 1 round, but can't use it to Hide.",
          "traits": []
        },
        {
          "id": "k2IoWqvvQDbUK6xn",
          "name": "Harrow Burst",
          "kind": "action",
          "description": "Raven unleashes a mass of magical harrow cards, dealing 15d8 slashing damage in a 30-foot emanation (check (reflex, dc:42, basic, options:area-effect) save). A creature that fails its save rolls 1d6 to determine a suit of cards: 1 = hammers (Strength), 2 = keys (Dexterity), 3 = shields (Constitution), 4 = books (Intelligence), 5 = stars (Wisdom), 6 = crowns (Charisma). The creature takes a –1 status penalty to all checks related to that ability score for 1 round (–2 status penalty on a critical failure). Raven can't use Harrow Burst again for 1d4.\nEffect: Harrow Burst",
          "traits": [
            "occult"
          ]
        }
