      "attacks": [],
      "actions": [
        {
          "id": "Bu3EUUlbn17nZdKq",
          "name": "Lifesense 60 feet",
          "kind": "passive",
          "description": "",
          "traits": []
        },
        {
          "id": "zaePCGVy6RdZ31CZ",
          "name": "See Magic",
          "kind": "passive",
          "description": "An algea can see magic auras on creatures or objects that it can observe; it can't see magic auras on creatures or objects that are hidden from its view. It learns the schools of magic for all spells affecting creatures.",
          "traits": []
        },
        {
          "id": "gOTq88NERumC1U4Q",
          "name": "+1 Status to All Saves vs. Magic",
          "kind": "passive",
          "description": "",
          "traits": []
        },
        {
          "id": "iAp1BgBeTFhgvNEP",
          "name": "Grieving Aura",
          "kind": "passive",
          "description": "30 feet. A creature that begins its turn in the aura must attempt a check (will, dc:27) save. Undead take a -2 circumstance penalty to this saving throw. The creature is then temporarily immune to the grieving aura for 1 hour.\nSuccess The creature is unaffected.\nFailure For 1 round, the creature can't use reactions and is Slowed 1 for that turn as it sobs uncontrollably.\nCritical Failure As failure, but the effects lasts while the creature remains in the aura plus 1 minute.",
          "traits": [
            "aura",
            "divine",
            "emotion",
            "mental"
          ]
        },
        {
          "id": "idd2T28Lmct79QDu",
          "name": "Drain Magic",
          "kind": "passive",
          "description": "Whenever a creature fails its save against Frenzied Beaks, the algea attempts to counter a spell effect active on that creature (6th level, counteract check +22). The algea can choose which effect to attempt to counteract for each creature.",
          "traits": [
            "divine"
          ]
        },
        {
          "id": "fmcgopzl3nvrBJkz",
          "name": "Frenzied Beaks",
          "kind": "action",
          "description": "Each foe in the swarm's space takes 5d6 piercing damage (check (reflex, dc:30, basic)) and is exposed to drain magic. This damage affects incorporeal creatures as if it had the effects of a ghost touch property rune.",
          "traits": []
        },
        {
          "id": "dCra4dM2DaOP8GAK",
          "name": "Soul Cage",
          "kind": "passive",
          "description": "An incorporeal undead damaged by Frenzied Beaks must attempt a check (will, dc:30) save.\nCritical Success The undead is unaffected and is temporarily immune for 24 hours.\nSuccess The undead takes a –10-foot status penalty to Speeds for 1 round.\nFailure As success, but the undead is also Immobilized for 1 round, although it can attempt to Escape (DC 30).\nCritical Failure The undead is restrained for 1 round. The algea can attempt to plane shift with the Restrained creature even if that creature isn't willing, but an unwilling creature can attempt a Will save to resist Interplanar Teleport. If it succeeds, the algea plane shifts and leaves the incorporeal creature behind, which is then no longer restrained.",
          "traits": [
            "divine",
            "incapacitation"
          ]
        }
      ],
      "spellcasting": [
        {
          "id": "XEk3qVgQOYlGTNiG",
          "name": "Innate Divine Spells",
          "tradition": "divine",
          "category": "innate",
          "attackModifier": 22,
          "saveDc": 30,
          "spells": [
            {
              "id": "5y912SAFBFLKiEnk",
              "name": "Invisibility",
              "rank": 2
            },
            {
              "id": "4r1maXXyxWGQipcS",
              "name": "Confusion",
              "rank": 4
            },
            {
              "id": "tsYIT3Ju2m5Vh3eT",
              "name": "Talking Corpse",
              "rank": 4
            },
            {
              "id": "MMUnQ4sqzntfVl13",
              "name": "Plane Shift (Self and soul caged creatures only, to the Boneyard only)",
              "rank": 7
            }
          ]
        }
      ]
