    "data": {
      "schemaVersion": 1,
      "entryType": "HAZARD",
      "name": "Spiky Pit Trap",
      "level": 4,
      "rarity": "common",
      "size": "medium",
      "traits": [],
      "description": "A piece of hide covered with a layer of dirt and gravel is suspended over a 20-foot pit filled with spikes.",
      "armorClass": 0,
      "hitPoints": 0,
      "hardness": 0,
      "stealth": {
        "modifier": 8,
        "details": "(trained)"
      },
      "disable": "check (thievery, dc:18) (trained) to manually trigger the trap without falling in, or check (thievery, dc:25) (trained) to secure the hide so the trap doesn't activate",
      "isComplex": false,
      "routine": "",
      "reset": "Creatures can still fall into the trap, but the hide that covers it must be reset manually (a 10-minute activity) for the trap to become Hidden again.",
      "saves": {
        "fortitude": 0,
        "reflex": 0,
        "will": 0
      },
      "defenses": {
        "immunities": [],
        "resistances": [],
        "weaknesses": []
      },
      "actions": [
        {
          "id": "yf2VZtO2S4eV7fKZ",
          "name": "Pitfall",
          "kind": "reaction",
          "description": "Trigger A creature or other large weight (such as the rushing waters of the previous trap) moves onto the gravel-covered hide\nEffect The triggering creature or object falls in and takes falling damage 10 bludgeoning damage) and is targeted by a spike's Strike. A falling creature can attempt to Grab an Edge with a check (reflex, dc:20) save (this becomes a check (reflex, dc:22) save if rushing waters are pouring into the pit).",
          "traits": []
        }
      ]
    }
