    "translatableHash": "sha256:d4134d25f5f1836a52d24ceecb2c4510d7c138adc755b3ffdc417c6e7fd8c9e0",
    "data": {
      "schemaVersion": 1,
      "name": "Corpse Sugi",
      "level": 12,
      "rarity": "uncommon",
      "size": "huge",
      "traits": [
        "evil",
        "undead",
        "unholy"
      ],
      "description": "Corpseroots are rotten, undead trees that grow bright-red poisonous fruit and spread blight to surrounding plants, transforming healthy trees into new corpseroots. These cunning killers drain the life from creatures through their root systems, posing as dead trees until their victims come within reach.\nCorpseroots most commonly form from rotten husks of trees that died from supernatural blights, making them common threats in the Fangwood and Fierani forests. The most powerful are ancient trees used as shrines and sacrificial altars, their roots absorbing the blood, flesh, and terror of those condemned under their boughs. Some of these ancient corpseroots still command the respect and devotion of the cults that inadvertently created them.",
      "armorClass": 32,
      "hitPoints": 242,
      "speedFeet": 20,
      "perception": {
        "modifier": 20,
        "senses": [
          "darkvision"
        ]
      },
      "saves": {
        "fortitude": 26,
        "reflex": 20,
        "will": 20
      },
      "abilities": {
        "str": 7,
        "dex": 3,
        "con": 5,
        "int": -2,
        "wis": 3,
        "cha": 2
      },
      "skills": {
        "athletics": 24,
        "stealth": 18
      },
      "languages": [
        "arboreal",
        "fey",
        "necril"
      ],
      "defenses": {
        "immunities": [
          "bleed",
          "death-effects",
          "disease",
          "paralyzed",
          "poison",
          "unconscious"
        ],
        "resistances": [
          "bludgeoning 10",
          "piercing 10"
        ],
        "weaknesses": [
          "axe-vulnerability 10",
          "fire 10"
        ]
      },
      "attacks": [
        {
          "id": "7spg3bnxup4hapkm",
          "name": "Branch",
          "bonus": 26,
          "damage": "1d6 mental; 3d12+10 bludgeoning",
          "traits": [
            "reach-15"
          ]
        },
        {
          "id": "5l8z97yi0fc0gqoq",
          "name": "Root",
          "bonus": 26,
          "damage": "3d12+10 bludgeoning; 1d6 mental",
          "traits": [
            "agile",
            "reach-20",
            "trip"
          ]
        },
        {
          "id": "fxc64qicfzi9l9lx",
          "name": "Rotten Fruit",
          "bonus": 22,
          "damage": "3d4+7 bludgeoning; 3d6 poison",
          "traits": [
            "splash"
          ]
        }
      ],
      "actions": [
        {
          "id": "lBbkmesWX20mQMJ5",
          "name": "Sugi Tree",
          "kind": "passive",
          "description": "When it isn't in danger, the corpse sugi spends 1 minute rooting to the earth, becoming planted in place. While the corpse sugi is planted and immobile, creatures must actively Seek and succeed at a check (perception, dc:38) Check to detect the Corpse Sugi's true nature.",
          "traits": []
        },
        {
          "id": "zu5kwhnrxafjmru7",
          "name": "Axe Vulnerability",
          "kind": "passive",
          "description": "The corpse sugi takes 10 additional damage from axes.",
          "traits": []
        },
        {
          "id": "loe7wunkt2aw95fw",
          "name": "Thoughtblight",
          "kind": "passive",
          "description": "30 feet. The mind of a non-nindoru sapient living creature that enters or starts their turn in the corpse sugi's aura becomes infested with invasive thoughts of cruelty and anguish, and must succeed at a check (will, dc:29) save or become Stupefied 1 (or Stupefied 2 on a critical failure). This condition persists for 1 minute after the creature leaves the aura. A creature that succeeds on the saving throw is temporarily immune to thoughtblight for 1 minute.",
          "traits": [
            "aura",
            "poison",
            "primal"
          ]
        },
        {
          "id": "KfMljjVvrcltFSTJ",
          "name": "Void Healing",
          "kind": "passive",
          "description": "",
          "traits": []
        },
        {
          "id": "u35onovz82ogkm7o",
          "name": "Take Root",
          "kind": "action",
          "description": "Frequency once per round\nRequirements The corpse sugi has a creature Grabbed or Restrained\nEffect The corpse sugi buries its roots into the creature, dealing 1d6+13 piercing damage and draining the target's life force (check (fortitude, dc:32, basic) save). On a failure, the creature is Drained 1 (or increases the value by 1 if already drained), and the corpse sugi regains 10 HP. If this would make a creature Drained 5, the creature dies.",
          "traits": [
            "primal"
          ]
        },
        {
          "id": "3qz1msK40lJzzqhO",
          "name": "Grab",
          "kind": "action",
          "description": "",
          "traits": []
        }
      ],
      "spellcasting": []
    }
