    "sourceHash": "sha256:72d5bf54402da112b2f3209438ea0c23fa0f7586f63e069ec2b14dc7089ea5af",
    "translatableHash": "sha256:496b4d535d393bc52a41531bdb6a0cd4be02eb3f25ba2e190e5c9126fa54f24a",
    "data": {
      "schemaVersion": 1,
      "entryType": "HAZARD",
      "name": "Spiral Seal",
      "level": 16,
      "rarity": "unique",
      "size": "medium",
      "traits": [
        "magical"
      ],
      "description": "A spiral shape suggesting the curling religious symbol of Pharasma is carved into the stone floor.",
      "armorClass": 39,
      "hitPoints": 106,
      "hardness": 27,
      "stealth": {
        "modifier": 0,
        "details": ""
      },
      "disable": "check (occultism, dc:37) (master) or check (religion, dc:40) (master) to unmake the Spiral Seal through occult ritual or prayer performed as a 10 minute activity with the Concentrate trait, or Dispel Magic (9th rank, counteract DC 40) to counteract the Spiral Seal.",
      "isComplex": false,
      "routine": "",
      "reset": "",
      "saves": {
        "fortitude": 30,
        "reflex": 25,
        "will": 0
      },
      "defenses": {
        "immunities": [
          "critical-hits",
          "precision"
        ],
        "resistances": [],
        "weaknesses": []
      },
      "actions": [
        {
          "id": "uox8BdqT7SHwPAXF",
          "name": "Backlash",
          "kind": "reaction",
          "description": "Trigger A creature fails an attempt to disable the Spiral Seal or inflicts damage to it without successfully breaking it\nEffect The magic stored within the Spiral Seal blasts outward in a concussive wave of power, surging in a spiraling vortex. All creatures within 60 feet of the Spiral Seal must attempt a check (fortitude, dc:41) save.\nCritical Success The creature is unaffected.\nSuccess The creature is knocked Prone.\nFailure The creature is knocked prone and is Stupefied 1 for 24 hours.\nCritical Failure The creature is knocked prone, is Stupefied 3 for 24 hours, and increases their Doomed value by 1.",
          "traits": [
            "incapacitation",
            "occult"
          ]
        },
        {
          "id": "ZiobchoAZw8EGQAl",
          "name": "Recovery",
          "kind": "passive",
          "description": "Frequency once per round\nTrigger The Spiral Seal is damaged but is above its Broken Threshold\nEffect The Spiral Seal repairs itself, regaining 30 healing Hit Points.",
          "traits": []
        }
      ]
    }
