        {
          "id": "Q78tMeRUfO7vehcO",
          "name": "Regeneration 50 (Deactivated by Fire or Void)",
          "kind": "passive",
          "description": "",
          "traits": []
        },
        {
          "id": "EaWA2WkRjbpm2GiI",
          "name": "Duplicate Victim",
          "kind": "reaction",
          "description": "Trigger The risen fetch critically hits a humanoid target with a fetch weapon Strike and has a Duplicate Foe spell available\nEffect The risen fetch casts duplicate foe on the target, who takes a -4 status penalty on the saving throw to resist.",
          "traits": [
            "occult"
          ]
        },
        {
          "id": "8GzTttsR8tPUpy3a",
          "name": "Manifest Fetch Weapon",
          "kind": "passive",
          "description": "Trigger The fetch starts its turn\nEffect A fetch weapon manifests in the fetch's hand. As soon as a fetch weapon is no longer wielded by a fetch, it vanishes. The fetch chooses the type of weapon it manifests, but it does not gain any of that weapon's standard weapon traits, instead using the traits listed above in the fetch weapon Strike.",
          "traits": [
            "primal"
          ]
        },
        {
          "id": "lqfoMvtMondVCDSV",
          "name": "Steady Spellcasting",
          "kind": "passive",
          "description": "If a reaction would disrupt the risen fetch's spellcasting action, the risen fetch attempts a check (flat, dc:15). On a success, the action isn't disrupted.",
          "traits": []
        }
