    "translatableHash": "sha256:81f42f20b2dbe3f6570d5366a2e85bf337f76a53a0450fa1144a37cf9c191c29",
    "data": {
      "schemaVersion": 1,
      "name": "Injured Sewer Ooze",
      "level": 0,
      "rarity": "common",
      "size": "medium",
      "traits": [
        "mindless",
        "ooze"
      ],
      "description": "These amorphous masses of sewage and other detritus make their way through filthy culverts beneath cities large and small.\nSlimes, molds, and other oozes can be found in dank dungeons and shadowed forests. While not necessarily evil, some grow to enormous sizes and have insatiable appetites.",
      "armorClass": 6,
      "hitPoints": 25,
      "speedFeet": 10,
      "perception": {
        "modifier": 1,
        "senses": [
          "motion-sense-60"
        ]
      },
      "saves": {
        "fortitude": 7,
        "reflex": -1,
        "will": 1
      },
      "abilities": {
        "str": 2,
        "dex": -5,
        "con": 4,
        "int": -5,
        "wis": 0,
        "cha": -5
      },
      "skills": {
        "stealth": -1
      },
      "languages": [],
      "defenses": {
        "immunities": [
          "acid",
          "critical-hits",
          "precision",
          "unconscious",
          "visual"
        ],
        "resistances": [],
        "weaknesses": []
      },
      "attacks": [
        {
          "id": "YXsM6AcguDWAwVIt",
          "name": "Pseudopod",
          "bonus": 8,
          "damage": "1d4+2 bludgeoning; 1d4 acid",
          "traits": [
            "unarmed"
          ]
        }
      ],
      "actions": [
        {
          "id": "VwrlDdZczBGO5Ps4",
          "name": "Motion Sense",
          "kind": "passive",
          "description": "A sewer ooze can sense nearby motion through vibration and air movement.",
          "traits": []
        },
        {
          "id": "mdqK7RuSjtezVyS8",
          "name": "Filth Wave",
          "kind": "action",
          "description": "Frequency once per minute\nEffect The sewer ooze unleashes a wave of filth, covering all creatures within a 20-foot emanation. Each creature in the area must succeed at a check (reflex, dc:15, options:area-effect,damaging-effect) save or take 1d4 acid damage and take a –10-foot penalty to its Speeds for 1 minute (on a critical failure, the creature also falls Prone). A creature can spend and Interact action to clean someone off, decreasing the Speed penalty by 5 feet with each action.",
          "traits": []
        }
      ],
      "spellcasting": []
    }
