    "sourceHash": "sha256:c6caa975a4dafc6799bc37dd23961a9244fe381222e4f2ca4db17d12a5b46d79",
    "translatableHash": "sha256:9aa1d013105789157002317ff2089b9ddb6e852c23c219c0c3ddb04e3ff4e685",
