      "actions": [
        {
          "id": "YMj2YteKtdg79DoF",
          "name": "Sneak Attack",
          "kind": "passive",
          "description": "The bugbear tormentor deals 1d6 extra precision damage to Off-Guard creatures.",
          "traits": []
        },
        {
          "id": "bpECAdKNxGcT7pXU",
          "name": "Twin Feint",
          "kind": "action",
          "description": "The bugbear raider makes a dazzling series of attacks with two weapons, using the first attack to throw their foe off guard against a second attack at a different angle. They make one Strike with each of their two melee weapons, both against the same target. The target is automatically Off-Guard against the second attack. Apply the bugbear radier's multiple attack penalty to the Strikes normally.",
          "traits": []
        }
      ],
