    "data": {
      "schemaVersion": 1,
      "name": "Bugbear Bully",
      "level": 4,
      "rarity": "common",
      "size": "medium",
      "traits": [
        "evil",
        "goblin",
        "humanoid",
        "lawful"
      ],
      "description": "These stealthy and cruel goblinoid creatures delight in spreading fear and tormenting their victims. Bugbears are the monsters lurking in the closet and hiding under the bed. Preying on remote farmsteads, bugbears reveal their presence with thumps in the night or creaks of boards to build lurking dread and arouse suspicion and fear.",
      "armorClass": 18,
      "hitPoints": 75,
      "speedFeet": 30,
      "perception": {
        "modifier": 7,
        "senses": [
          "darkvision",
          "scent-imprecise-30"
        ]
      },
      "saves": {
        "fortitude": 14,
        "reflex": 9,
        "will": 8
      },
      "abilities": {
        "str": 5,
        "dex": 2,
        "con": 3,
        "int": -1,
        "wis": 1,
        "cha": 0
      },
      "skills": {
        "acrobatics": 10,
        "athletics": 12,
        "intimidation": 8,
        "stealth": 8
      },
      "languages": [
        "aklo",
        "common",
        "goblin"
      ],
      "defenses": {
        "immunities": [],
        "resistances": [],
        "weaknesses": []
      },
      "attacks": [
        {
          "id": "7Wx3eTGO2HVqHxqh",
          "name": "Greatclub",
          "bonus": 10,
          "damage": "1d10+7 bludgeoning",
          "traits": [
            "backswing",
            "shove"
          ]
        }
      ],
      "actions": [
        {
          "id": "ORE3NapxjXjifDBn",
          "name": "Brute Force",
          "kind": "action",
          "description": "The bugbear bully strides up to half its speed and then attempts to either Shove: Athletics or Trip: Athletics a creature. If they critically fail, they treat the result as a failure.",
          "traits": []
        },
        {
          "id": "hKKLqWLa3L49oSoS",
          "name": "Bully's Rage",
          "kind": "action",
          "description": "Requirements The bugbear bully has dealt damage to a creature or knocked a creature Prone since the start of its previous turn\nEffect The bully gains a +2 status bonus to Intimidation checks and damage until the end of its turn.\nEffect: Bully's Rage",
          "traits": []
        }
      ],
      "spellcasting": []
    }
