        {
          "id": "QNy9Hrx2ib5tkQKt",
          "name": "Shadow Blend",
          "kind": "passive",
          "description": "The shadow drake's form shifts and blends reflexively with surrounding shadows. A shadow drake gains an additional reaction each round, but it can use this reaction only for Shadow Evade.",
          "traits": []
        },
        {
          "id": "0VNX7MbrCqRSKYkE",
          "name": "Shadow Evade",
          "kind": "reaction",
          "description": "Trigger A creature attacks the shadow drake while it is in an area of dim light\nEffect The shadow drake further obscures its position. The attacker must succeed at a check (flat, dc:11) check in order to affect the shadow drake, as if the drake were Hidden for the triggering attack.",
          "traits": []
        },
        {
          "id": "wnZi8QCOMG86Db4l",
          "name": "Draconic Frenzy",
          "kind": "action",
          "description": "The shadow drake makes one bite Strike and two tail Strikes in any order.",
          "traits": []
        },
        {
          "id": "usIKpszaYrCWfN8r",
          "name": "Shadow Breath",
          "kind": "action",
          "description": "A shadow drake spits a ball of black liquid that explodes into a cloud of frigid black shadow. This attack has a range of 40 feet and explodes in a 5-foot burst. Creatures within the burst take 3d6+4 cold damage (check (reflex, dc:20, basic, options:area-effect) save). The explosion of shadow also snuffs out mundane light sources the size of a torch, lantern, or smaller, and attempts to counteract magical light with a 1d20+10 counteract modifier.\nThe shadow drake can't use Shadow Breath again for 1d6 rounds.",
          "traits": [
            "arcane",
            "cold",
            "shadow"
          ]
        },
        {
          "id": "5IixHzakyftZgS0g",
          "name": "Speed Surge",
          "kind": "action",
          "description": "Frequency three times per day\nEffect The shadow drake Strides or Flies twice.",
          "traits": []
        }
