    "data": {
      "schemaVersion": 1,
      "entryType": "HAZARD",
      "name": "Hallways Full of Mostly Illusory Opossums",
      "level": 3,
      "rarity": "common",
      "size": "medium",
      "traits": [
        "environmental",
        "magical"
      ],
      "description": "Several distressed opossums dressed in school uniforms and under the effects of Mirror Image fly about the hallway, guided by four giggling sprites.",
      "armorClass": 22,
      "hitPoints": 46,
      "hardness": 0,
      "stealth": {
        "modifier": 7,
        "details": ""
      },
      "disable": "check (diplomacy, dc:20), check (deception, dc:20), or check (intimidation, dc:20) four times to convince one sprite to undo their spells; check (athletics, dc:22), check (diplomacy, dc:22) (with wild empathy) or check (nature, dc:22) to subdue or soothe the opossums; or Dispel Magic (2nd rank; counteract DC 18) to undo one sprites' worth of spells. Four successes are required to disable the hazard.",
      "isComplex": false,
      "routine": "(4 actions) The hazard loses 1 action each turn for each Disable success. Each sprite takes one action to Strike a different randomly chosen PC.",
      "reset": "",
      "saves": {
        "fortitude": 14,
        "reflex": 12,
        "will": 0
      },
      "defenses": {
        "immunities": [
          "precision",
          "swarm-mind"
        ],
        "resistances": [],
        "weaknesses": [
          "area-damage 5",
          "splash-damage 5"
        ]
      },
      "actions": [
        {
          "id": "J520gSXDYhC7PBjH",
          "name": "Swarm Mind",
          "kind": "passive",
          "description": "",
          "traits": []
        },
        {
          "id": "tLPGiuv2qFnsy3k8",
          "name": "New Targets",
          "kind": "reaction",
          "description": "Trigger A creature walks into the room\nEffect The sprites scream \"Surprise!,\" attempt a opossum flyby Strike, and roll initiative.",
          "traits": []
        }
      ]
    }
