      "level": 4,
      "rarity": "uncommon",
      "size": "medium",
      "traits": [
        "magical",
        "trap"
      ],
      "description": "A book unfurls and its case forms into a leathery locust, its pages folding into an overwhelming swarm.",
      "armorClass": 21,
      "hitPoints": 46,
      "hardness": 0,
      "stealth": {
        "modifier": 22,
        "details": "(trained)"
      },
